// Shape the webhook body into the research API request. Validation lives in
// the API (one source of truth): bad input comes back as its 422 response.
const src = $('Topic intake').first().json;
const d = src.body ?? {};
const headers = src.headers ?? {};
const pick = (k) => (d[k] === undefined || d[k] === null || d[k] === '') ? undefined : d[k];
const request = {
  topic: typeof d.topic === 'string' ? d.topic.trim() : d.topic,
  language: pick('language'),
  country: pick('country'),
  audience: pick('audience'),
  style: pick('style'),
  lookback_days: pick('lookback_days'),
  target_duration_s: pick('target_duration_s'),
  audience_goal: pick('audience_goal'),
  channels: pick('channels'),
  clips_per_run: pick('clips_per_run'),
  daily_budget_usd: pick('daily_budget_usd'),
  // Retries with the same key return the same job instead of a new one.
  idempotency_key: pick('idempotency_key') ?? headers['idempotency-key'],
};
Object.keys(request).forEach((k) => request[k] === undefined && delete request[k]);
return [{ json: { request } }];
